class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.freq = {}

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        freq = self.freq.get(key, 0)
        del self.freq[key]
        if not self.freq:
            del self.freq[self.capacity - 1]
            self.cache.pop(key)
        self.freq[key] = freq + 1
        if not self.cache:
            self.capacity -= 1
        return -1

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.freq:
            del self.freq[key]
        if len(self.freq) == self.capacity - 1:
            key_to_remove = min(self.freq, key=self.frequency_key)
            del self.freq[key_to_remove]
            del self.cache[key_to_remove]
