from heapq import *


def window_medians(a, k):
    n = len(a)
    if n < k:
        return []

    # Helper function to merge two sorted lists
    def merge_halves(a, b):
        i, j = 0, 0
        result = []
        while i < len(a) and j < len(b):
            if a[i] < b[j]:
                result.append(a[i])
                i += 1
            else:
                result.append(b[j])
                j += 1
        result.extend(a[i:])
        result.extend(b[j:])
        return result

    def find_median_indices(a, k):
        n = len(a)
        medians = []
        for i in range(n - k + 1):
            mid = (n + k) // 2
            if i + k - 1 < n:
                mid = min(mid, n - (i + k) % (k * 2))
            if i & 1:
                med = a[i + k // 2 - 1]
            else:
                mid = i + (n - i) % k
            if i & 1:
                med = max(med, a[i + (k - 1) // 2])
            else:
                mid = i + (n - i) % k
            medians.append(med)
        return medians

    if k > n:
        return []

    mid = (n + 1) // 2
    medians = [a[i] for i in range(n - k + 1)]
    for i in range(1, n - k + 2):
        med = (medians[i-1] + medians[i-1]) // 2
        if i & 1:
            med = max(med, a[i-1])
        medians.append(med)
    return medians

