const { promisify } = require('util');
const _ = require('lodash');

function pLimit(n) {
  const queue = [];
  let current = 0;

  function enqueue(fn, ...args) {
    return new Promise((resolve, reject) => {
      const id = Symbol('p-' + current++);
      let called = false;
      try {
        const result = fn(...args).then(res => {
          if (called) return;
            called = true;
          resolve(result);
        }).catch(err => {
          if (called) return;
          reject(new Error(`Failed to call function with args: ${args}`));
      });
    });

    return new Promise((resolve, reject) => {
      if (current < n) {
        queue.push({ resolve, reject, promise: result });
        return;
      }
      const job = (id) => {
        if (current < n) {
          current++;
          result.then(res => resolve(res), err => reject(err));
        } else {
          // Handle error in the next iteration
          if (current > 0) current--;
        }
      };
      result.then(job);
    });
  }

  return enqueue;
}

module.exports = pLimit;
