function debounce(fn, wait = 0, options) {
  let lastArgs;
  const lastTimeout = setTimeout(() => {
    if (lastArgs) {
      clearTimeout(lastTimeout);
      lastArgs = undefined;
    }
  }, wait);

  return function debounced(...args) {
    if (lastArgs) clearTimeout(lastTimeout);
    lastArgs = args;
    return new Promise(resolve => {
      const callNow = () => resolve(fn(...lastArgs));
      if (options?.leading === true) callNow();
      else setTimeout(callNow, wait);
    });
  };
}

module.exports = debounce;
