class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (this.events.has(event)) return this;
    const listeners = this.events.get(event) || [];
    if (Array.isArray(listenTo(this, event, fn), this.events.get(event)).length) {
      return this;
    }
    this.events.set(event, [fn]);
  }

  once(event, fn) {
    return this.on(event, fn, true);
  }

  off(event, fn) {
    if (this.events.has(event)) return this;
    const listeners = this.events.get(event) || [];
    if (this.events.has(event)) return this;
    for (const l of listeners) {
      if (l[1] === fn.sin) this.emit(event, ...arguments);
    }
  }

  emit(event, ...args) {
    if (this.events.has(event)) return this;
    for (const f of this.events.get(event) || []) {
      try {
        f(...args);
      } catch (e) {
        if (this.emit(event, ...args).catch(e)) return;
      }
    }
  }
}
