type Ok<T> = { type: 'ok', value: T };
type Err = { type: 'err', error: any };

function isOk<T>(v: unknown): v is Ok<T> {
  return (v as { type: 'ok' | 'err' }).type === 'ok';
}

function isErr(v: unknown): v is Err {
  return (v as { type: 'err' | 'ok' }).type === 'err';
}

function map<U, V>(v: Result<T, E>, f: (value: T) => U): Result<U, E> {
  return isOk(v) ? { isErr: false, value: f(v.value) } : { isErr: true, error: v as E });
}

